"""Data-driven HUD rings and segmented meters, rendered without external assets."""
from html import escape
from base64 import b64encode
import math


def ring(percent,label,detail='',large=False,identity='main'):
    percent=max(0,min(100,percent));radius=85;circumference=2*math.pi*radius
    ticks=[]
    for index in range(60):
        angle=math.radians(index*6-90)
        outer=113;inner=103 if index%5 else 98
        color='#00e9f4' if index<percent*.6 else '#21455c'
        if index%5==0 and index>=percent*.6:color='#f58135'
        ticks.append(f'<line x1="{130+inner*math.cos(angle):.2f}" y1="{130+inner*math.sin(angle):.2f}" x2="{130+outer*math.cos(angle):.2f}" y2="{130+outer*math.sin(angle):.2f}" stroke="{color}" stroke-width="2"/>')
    value=f'{percent:.0f}%'
    svg=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 260 260" role="img" aria-label="{escape(label)}: {value}" class="hud-ring {'large' if large else 'small'}">
    <circle cx="130" cy="130" r="122" fill="none" stroke="#f58135" stroke-width="1" stroke-dasharray="450 75" transform="rotate(-125 130 130)"/>
    {''.join(ticks)}
    <circle cx="130" cy="130" r="93" fill="none" stroke="#00c7e466" stroke-width="1"/>
    <circle cx="130" cy="130" r="85" fill="#031627" stroke="#163d53" stroke-width="10"/>
    <circle cx="130" cy="130" r="85" fill="none" stroke="#00e9f4" stroke-width="10" stroke-dasharray="{circumference*percent/100:.2f} {circumference:.2f}" transform="rotate(-90 130 130)"/>
    <circle cx="130" cy="130" r="72" fill="none" stroke="#08788e" stroke-width="1" stroke-dasharray="310 50"/>
    <circle cx="130" cy="130" r="65" fill="#0a344a" stroke="#0c6074" stroke-width="1"/>
    <text x="130" y="140" text-anchor="middle" fill="#e1fcff" font-family="Consolas,monospace" font-size="37">{value}</text>
    </svg>'''
    source=b64encode(svg.encode('utf-8')).decode('ascii')
    visual=f'<img class="hud-ring {"large" if large else "small"}" src="data:image/svg+xml;base64,{source}" alt="{escape(label)}: {value}"/>'
    return '<div class="hud-gauge">'+visual+'<span>'+escape(label)+'</span><small>'+escape(detail)+'</small></div>'


def meter(label,value,detail):
    lit=round(36*max(0,min(100,value))/100)
    bars=''.join('<i class="'+('on' if index<lit else '')+(' warm' if index>=29 else '')+'"></i>' for index in range(36))
    return '<div class="hud-meter"><header><span>'+escape(label)+'</span><b>'+escape(detail)+'</b></header><div class="hud-segments">'+bars+'</div></div>'


def console(data,diagnostics,counts,analyzed,status):
    total=data['total'];classified=sum(counts.values());coverage=100*analyzed/total if total else 0
    active=len({row['Data'] for row in data['daily'] if row['Partidas']})
    phase_total=diagnostics['total'];phase_done=diagnostics['analyzed']
    mini=[('Vitórias',data['totals'].get('wins',0)),('Derrotas',data['totals'].get('losses',0)),('Empates',data['totals'].get('draws',0))]
    gauges=''.join('<div>'+ring(100*number/total if total else 0,label,str(number)+(' partida' if number==1 else ' partidas'),identity=label)+'</div>' for label,number in mini)
    gauges+='<div>'+ring(100*phase_done/max(1,phase_total),'Diagnóstico',f'{phase_done}/{phase_total} partidas',identity='phases')+'</div>'
    state='ANALISANDO NOVAS PARTIDAS' if status.get('current') else 'FILA DE ANÁLISE ATIVA' if status.get('queued') else 'RELATÓRIOS SINCRONIZADOS' if analyzed==total else 'PREPARANDO CLASSIFICAÇÃO'
    return '<div class="hud-console"><div class="hud-main-gauge"><div class="hud-caption">01 / CLASSIFICAÇÃO DE LANCES</div>'+ring(coverage,'COBERTURA DO PERÍODO',f'{analyzed} de {total} partidas',True)+'</div><div class="hud-console-data"><div class="hud-status"><i></i>'+state+'<span>COACH / STOCKFISH</span></div><div class="dash-kpis">'+gauges+'</div><div class="hud-meter-grid">'+meter('PARTIDAS CLASSIFICADAS',coverage,f'{analyzed}/{total}')+meter('SEUS LANCES AVALIADOS',100*classified/max(1,data['moves']),f'{classified}/{data["moves"]}')+'</div><div class="hud-readings"><span><b>'+str(total)+'</b> PARTIDAS</span><span><b>'+f'{data["moves"]/max(1,total):.1f}'.replace('.',',')+'</b> LANCES / PARTIDA</span><span><b>'+str(active)+'</b> DIAS ATIVOS</span></div></div></div>'


